## Torah Corpus

**Endpoint:** GET /webhook/torah-corpus

**Description:** Liste des 9 corpus du catalogue Torah.

**Response:**
```json
{
  "success": true,
  "corpus": [
    {
      "id": "uuid",
      "name": "Bavli",
      "hebrew_name": "בבלי",
      "aliases": {...}
    }
  ],
  "count": 9
}
```

parameters.jsCode:
// Format API response
const input = $input.first().json;
// Avec onError=continueRegularOutput, un appel en échec ne produit PAS
// {statusCode, body} : n8n émet l'objet d'erreur, sans statusCode, et avec un
// code TEXTUEL (« ERR_BAD_REQUEST »). Le statut réel n'existe que dans le
// message, sous la forme « 404 - {...} ».
// Sans cette lecture, `input.statusCode || 200` retombait sur 200, le spread
// recopiait error.code = "ERR_BAD_REQUEST", et Respond refusait une chaine comme
// code HTTP : un seder inconnu sortait en HTTP 500 « Invalid status code »
// au lieu d'un 404 NOT_FOUND. Meme parade que n8n-workflows#422.
let statusCode = input.statusCode;
if (statusCode === undefined) {
  const brut = String(input?.error?.message || input?.message || '');
  const m = brut.match(/(\d{3})\s*-\s*/);
  statusCode = m ? parseInt(m[1], 10) : ((input?.error || input?.code) ? 502 : 200);
}
// Sur echec, input.body est absent : `data` vaut l'objet d'erreur. On tente d'en
// extraire le corps JSON de l'API, sinon on garde le message brut.
let data = input.body;
if (data === undefined) {
  const brut = String(input?.error?.message || input?.message || '');
  const j = brut.match(/\{[\s\S]*\}/);
  try { data = j ? JSON.parse(j[0]) : { message: brut || 'Erreur API' }; }
  catch (e) { data = { message: brut || 'Erreur API' }; }
}

// API error
if (statusCode >= 400) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.detail?.message || (typeof data.detail === 'string' ? data.detail : null) || data.message || 'Erreur API',
        status: statusCode === 404 ? 'NOT_FOUND' : 'API_ERROR'
      }
    }
  }];
}

// Success response
return [{
  json: {
    success: true,
    ...data
  }
}];

// `include` est relayé TEL QUEL, sans liste blanche locale : c'est l'API qui
// connaît les valeurs acceptées, et dupliquer cette connaissance ici créerait
// deux sources de vérité qui divergeraient au premier ajout côté API.
//
// À la date d'écriture elle accepte « counts » et « status », et refuse le reste
// en 400 avec la liste des valeurs valides — un message plus utile que tout ce
// qu'on pourrait produire. Note : « progress » est renvoyé AVEC « status », mais
// n'est pas une valeur d'include recevable (azy.daily#249).
const input = $input.first().json;
const query = input.query || {};

const include = (query.include || '').trim();

return [{ json: { include: include || null,
                  requete: include ? '?include=' + encodeURIComponent(include) : '' } }];

